For any $k \in \mathbf{Z}_{\ge 3}$ and $q_1, \ldots, q_k \in [1, \infty)$ with $\sum_i \frac{1}{q_i} > 1$, and any $\epsilon, K, C > 0$, there exist $\delta, \tau > 0$ such that the following holds.
Let $(X_i, \mathbf{P}_i)$ be finite probability spaces and $f_{i} : X_i \times X_{i+1} \to [0, \infty)$, for $i \in \mathbf{Z}/k\mathbf{Z}$. Assume that for each $i$,
\begin{itemize}
    \item[$(i)$] \emph{(Bounded Schatten norm).} One has $||f_{i}||_{S^{q_i}} \le C$, and
    \item[$(ii)$] \emph{(Dense pairs condition with large parts).} For any partitions $\mathcal{P}_i, \mathcal{P}_{i+1}$ of $X_i, X_{i+1}$ into parts with probabilities $\ge \tau$, one has
    \begin{equation} 
        ||f_{i}\mathbbm{1}_{\mathbf{E}(f_{i} \mid \mathcal{P}_i \otimes \mathcal{P}_{i+1}) > K} ||_{L^1} \le \epsilon/4.
    \end{equation}
\end{itemize}
If additionally
\begin{equation} 
    \mathbf{E}_{x_1, \ldots, x_k} \prod_{i=1}^k f_{i}(x_i,x_{i+1}) \le \delta,
\end{equation}
then there exist subsets $E_{i} \subset X_i \times X_{i+1}$ with $||f_{i} \mathbbm{1}_{E_{i}^c}||_{L^1} \le \epsilon$ for each $i$, such that
\[
    \mathbf{E}_{x_1, \ldots, x_k} \prod_{i=1}^k \mathbbm{1}_{E_{i}}(x_i,x_{i+1}) = 0.
\]

Moreover, if all $(X_i, \mathbf{P}_i) = (X, \mathbf{P})$ are equal and $\mathbf{P}$ is the uniform distribution, and $|X|$ is sufficiently large in terms of $k,q_1,\ldots,q_k,\epsilon,K,C$, then in the dense pairs condition one can assume that $\mathcal{P}_i = \mathcal{P}_{i+1}$, and one can replace 6.3 with $\mathbf{E}_{x_1, \ldots, x_k}\mathbbm{1}_{x_1,\ldots,x_k\textnormal{ distinct}} \prod_{i=1}^k f_{i}(x_i,x_{i+1})  \le \delta$. If additionally all $f_i = f$ are equal, then one can also replace 6.2 with $||f\mathbbm{1}_{\mathbf{E}(f \mid \mathcal{P} \otimes \mathcal{P}) > K} \mathbbm{1}_{\textnormal{diag}(\mathcal{P})^c}||_{L^1} \le \epsilon/8$.
